// HTML to Plain Text Converter for n8n Code Node
// Processes all incoming items and outputs one combined plain text bundle

function htmlToPlainText(html) {
  let text = html;

  // Remove script and style elements completely
  text = text.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');

  // Replace common block elements with line breaks
  text = text.replace(/<\/?(div|p|br|h[1-6]|li|tr)[^>]*>/gi, '\n');

  // Replace list items with bullet points
  text = text.replace(/<li[^>]*>/gi, '• ');

  // Remove all remaining HTML tags
  text = text.replace(/<[^>]*>/g, '');

  // Decode common HTML entities
  const entityMap = {
    '&amp;': '&',
    '&lt;': '<',
    '&gt;': '>',
    '&quot;': '"',
    '&#39;': "'",
    '&apos;': "'",
    '&nbsp;': ' ',
    '&copy;': '©',
    '&reg;': '®',
    '&trade;': '™',
    '&hellip;': '...',
    '&mdash;': '—',
    '&ndash;': '–'
  };

  for (const [entity, char] of Object.entries(entityMap)) {
    text = text.replace(new RegExp(entity, 'g'), char);
  }

  // Decode numeric HTML entities (e.g., &#123;)
  text = text.replace(/&#(\d+);/g, (_, dec) => String.fromCharCode(dec));

  // Decode hex HTML entities (e.g., &#x1F;)
  text = text.replace(/&#x([0-9A-Fa-f]+);/g, (_, hex) =>
    String.fromCharCode(parseInt(hex, 16))
  );

  // Clean up whitespace
  text = text.replace(/\n\s*\n/g, '\n\n'); // Remove excessive line breaks
  text = text.replace(/[ \t]+/g, ' ');     // Replace multiple spaces/tabs
  text = text.trim();                      // Remove leading/trailing whitespace

  return text;
}

try {
  // Process each incoming item
  const processed = items.map((item, index) => {
    const htmlContent = item.json.data || "";
    const plainText = htmlToPlainText(htmlContent);

    return {
      index,
      originalHtml: htmlContent,
      plainText,
      characterCount: plainText.length,
      wordCount: plainText.split(/\s+/).filter(word => word.length > 0).length,
    };
  });

  // Combine all plain texts into one big text block
  const combinedPlainText = processed.map(
    (p, i) => `--- Item ${i + 1} ---\n${p.plainText}`
  ).join("\n\n");

  return [{
    json: {
      combinedPlainText,
      totalItems: processed.length,
      details: processed,
      success: true
    }
  }];
} catch (error) {
  return [{
    json: {
      error: `Failed to convert HTML to text: ${error.message}`,
      success: false
    }
  }];
}

// Input: array of items with `output` (stringified JSON or JSON array)
// Goal: produce one item with formatted HTML for email

function safeParse(str) {
  try {
    return JSON.parse(str);
  } catch (e) {
    return null;
  }
}

// Flatten and parse outputs
let allEntries = [];

for (const item of items) {
  let parsed = safeParse(item.json.output);
  if (!parsed) continue;

  if (Array.isArray(parsed)) {
    allEntries.push(...parsed);
  } else {
    allEntries.push(parsed);
  }
}

// Group by Competitor
const grouped = {};
for (const entry of allEntries) {
  if (!grouped[entry.Competitor]) {
    grouped[entry.Competitor] = [];
  }
  grouped[entry.Competitor].push(entry);
}

// Generate HTML
let html = `
  <html>
  <head>
    <style>
      body { font-family: Arial, sans-serif; line-height: 1.5; }
      h2 { color: #2c3e50; margin-top: 30px; }
      h3 { color: #34495e; margin-top: 20px; }
      ul { margin: 0; padding-left: 20px; }
      li { margin-bottom: 6px; }
      .source { font-style: italic; color: #7f8c8d; }
      .section { margin-bottom: 15px; }
    </style>
  </head>
  <body>
    <h1>🕵️ Competitor Insights Report</h1>
`;

for (const competitor of Object.keys(grouped)) {
  html += `<h2>🏷️ ${competitor}</h2>`;

  for (const sourceEntry of grouped[competitor]) {
    html += `<h3>🔎 Source: ${sourceEntry.Source}</h3>`;

    html += `<div class="section"><strong>📊 Sentiment:</strong> ${sourceEntry.SentimentSummary || "N/A"}</div>`;

    if (sourceEntry.PainPoints?.length) {
      html += `<div class="section"><strong>❌ Pain Points:</strong><ul>`;
      for (const p of sourceEntry.PainPoints) {
        html += `<li>${p}</li>`;
      }
      html += `</ul></div>`;
    }

    if (sourceEntry.RequestedFeatures?.length) {
      html += `<div class="section"><strong>✨ Requested Features:</strong><ul>`;
      for (const f of sourceEntry.RequestedFeatures) {
        html += `<li>${f}</li>`;
      }
      html += `</ul></div>`;
    }

    if (sourceEntry.Strengths?.length) {
      html += `<div class="section"><strong>💪 Strengths:</strong><ul>`;
      for (const s of sourceEntry.Strengths) {
        html += `<li>${s}</li>`;
      }
      html += `</ul></div>`;
    }

    if (sourceEntry.OtherInsights?.length) {
      html += `<div class="section"><strong>💡 Other Insights:</strong><ul>`;
      for (const o of sourceEntry.OtherInsights) {
        html += `<li>${o}</li>`;
      }
      html += `</ul></div>`;
    }
  }
}

html += `
  </body>
  </html>
`;

// Return as single item for Gmail node
return [{ json: { html } }];
